import {sourceSnapshot} from './sources.mjs';
import {observerWorkspace,observerPanel,observerSelection} from './observer.mjs';
import{client,configured,verifiedUser,workspace,bootstrap,revision,command,recordCommand,accountCommand,errorText}from'./api.mjs';
import{FIELDS,PERIODS,LEVELS,COMPETENCIES,ACTIVITIES,latest,agreed,lastCheck,round,RULE,today,programMonth}from'./domain.mjs';
const $=s=>document.querySelector('#assessment').querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),query=new URLSearchParams(location.search);
const labels={mentee:'Mentee',asmen:'Asisten Mentor',mentor:'Mentor',program:'Tim Program',finance:'Bendahara',system:'Super Admin'};
let observerState=null;const pendingRequests=new WeakMap();
let w,role,rev=0,busy=false,dirty=false,editor=null;
const names={poc:'poc',abc:'abc',progres:'progres',penilaian:'review',raport:'raport','kelompok-penilaian':'kelompok',observer:'observer'};
const page=names[location.pathname.split('/').pop().replace('.html','')]||'review',route=[page];
const appBase=new URL('../../app/',import.meta.url);
const sections={poc:'Personal Outcome Contract',abc:'Worksheet ABC',progres:'Progres & bukti',review:'Penilaian',penilaian:'Penilaian akhir',raport:'Raport',peserta:'Peserta & kelompok',sistem:'Pengguna & sistem',keuangan:'Keuangan',kelompok:'Kelompok',beranda:'Beranda'};
const stamp=s=>s?new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}).format(new Date(s))+' WIB':'—';
const day=s=>{try{return s?new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium'}).format(new Date(s.length===10?s+'T12:00:00+07:00':s)):'—';}catch{return 'Tanggal belum benar';}};
const number=n=>n===null||n===undefined?'—':Number(n).toLocaleString('id-ID',{maximumFractionDigits:2});
const cohort=()=>w?.cohorts.find(c=>c.id===w.selectedCohort);
const profile=id=>w?.profiles.find(p=>p.id===id);
const me=()=>w.actor;
const currentM=()=>cohort()?programMonth(cohort().starts_on):1;
const month=()=>PERIODS.includes(Number(query.get('period')))?Number(query.get('period')):PERIODS.find(m=>m>=currentM())||12;
const group=()=>w.groups.find(g=>g.active&&w.members.some(m=>m.group_id===g.id&&m.user_id===w.selectedMentee&&m.active));
const owns=()=>role==='mentee'&&w.selectedMentee===me().id;
const assigned=r=>{const g=group();return g&&g[r==='asmen'?'asmen_id':'mentor_id']===me().id&&me().roles.includes(r);};
const assessor=()=>me().roles.includes('program')&&w.staff.some(s=>s.user_id===me().id&&s.can_assess);
const manager=()=>me().roles.includes('system')||me().roles.includes('program')&&w.staff.some(s=>s.user_id===me().id&&s.can_manage);
function url(part,extra={}){const p=new URLSearchParams({peran:query.get('peran')||'mentee'});if(w?.selectedCohort)p.set('cohort',w.selectedCohort);if(w?.selectedMentee)p.set('mentee',w.selectedMentee);if(w?.selectedMentee&&group())p.set('group',group().id);if(query.get('period'))p.set('period',query.get('period'));if(query.get('record')||query.get('source'))p.set('source',query.get('record')||query.get('source'));for(const[k,v]of Object.entries(extra))if(v!==null&&v!==undefined)p.set(k,v);const last=part.split('/').pop(),files={review:'penilaian',penilaian:'penilaian',kelompok:'kelompok-penilaian',sistem:'super-admin',peserta:'super-admin',beranda:'beranda-mentee'};return new URL((files[last]||last)+'.html',appBase).pathname+(p.size?'?'+p:'');}
const subjectURL=(part,extra)=>url((role==='mentee'?'program':'kelompok')+'/'+part,extra);
const badge=(s,cls='')=>`<span class="badge ${esc(cls)}">${esc(s)}</span>`;
const empty=(title,text,cta='')=>`<section class="card empty"><span class="empty-mark" aria-hidden="true">↗</span><h2>${esc(title)}</h2><p class="sub" style="margin:10px auto 0">${esc(text)}</p>${cta?'<div class="actions" style="justify-content:center">'+cta+'</div>':''}</section>`;
const button=(text,attrs='',secondary=false)=>`<button type="button" class="${secondary?'secondary':'button'}" ${attrs}>${esc(text)}</button>`;
const link=(text,href,cls='secondary')=>`<a class="${cls}" href="${esc(href)}">${esc(text)}</a>`;
function inform(text,type=''){const m=$('#message');m.textContent=text;m.className='notice '+type;if(type==='error')m.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function field(name,label,value='',type='text',help='',attributes=''){
 const input=type==='textarea'?`<textarea name="${esc(name)}" rows="3" ${attributes}>${esc(value)}</textarea>`:type==='checkbox'?`<input type="checkbox" name="${esc(name)}" ${value?'checked':''} ${attributes}>`: `<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${attributes}>`;
 return`<label class="${type==='checkbox'?'check':''}">${type==='checkbox'?input:''}${esc(label)}${type!=='checkbox'?input:''}${help?`<small class="help">${esc(help)}</small>`:''}</label>`;
}
function select(name,label,options,value='',help='',attrs=''){return`<label>${esc(label)}<select name="${esc(name)}" ${attrs}><option value="">Pilih…</option>${options.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>${help?`<small class="help">${esc(help)}</small>`:''}</label>`;}
const hidden=(name,value)=>`<input type="hidden" name="${esc(name)}" value="${esc(value)}">`;
function get(obj,path){return path.split('.').reduce((a,k)=>a?.[k],obj);}
function set(obj,path,value){const keys=path.split('.');let o=obj;keys.forEach((k,i)=>{if(i===keys.length-1)o[k]=value;else{o[k]??=/^\d+$/.test(keys[i+1])?[]:{};o=o[k];}});}
function read(form){const data={};for(const el of form.elements){if(!el.name||el.disabled||el.type==='submit'||el.type==='button')continue;let v=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'||el.dataset.number!==undefined)v=v===''?'':Number(v);set(data,el.name,v);}return data;}
function permissionsEmpty(){if(!w.selectedCohort)return empty('Belum ada cohort','Pengelola perlu menyiapkan cohort, akun peserta, dan penugasannya terlebih dahulu.',me().roles.includes('system')?link('Siapkan cohort',url('sistem')):'');if(!w.selectedMentee)return empty('Belum ada mentee yang dapat dibuka','Data pendampingan muncul setelah mentee dan pendamping ditugaskan ke kelompok aktif.');return'';}
function title(t,sub='',action=''){return`<div class="page-title"><div><h1>${esc(t)}</h1>${sub?`<p class="sub">${esc(sub)}</p>`:''}</div>${action}</div>`;}
function context(){
 let out=me().roles.length>1?`<label>Akses akun<select id="assessment-role">${me().roles.map(r=>`<option value="${esc(r)}" ${r===role?'selected':''}>${esc(labels[r])}</option>`).join('')}</select></label>`:'';if(w.cohorts.length)out+=`<div class="context"><label>Cohort<select id="cohort-select">${w.cohorts.map(c=>`<option value="${c.id}" ${c.id===w.selectedCohort?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`;
 const people=w.enrolments.filter(e=>e.role==='mentee'&&e.active&&profile(e.user_id));if(people.length&&role!=='mentee'&&!['system','finance'].includes(role))out+=`<label>Mentee<select id="mentee-select">${people.map(p=>`<option value="${p.user_id}" ${p.user_id===w.selectedMentee?'selected':''}>${esc(profile(p.user_id).display_name)}</option>`).join('')}</select></label>`;
 if(w.cohorts.length)out+='</div>';
 if(w.selectedMentee&&!['system','finance'].includes(role)&&['poc','abc','progres','review','raport','penilaian'].includes(page))out+=`<div class="subject-tabs">${['poc','abc','progres','review','raport'].map(p=>`<a class="${page===p||page==='penilaian'&&p==='review'?'current':''}" href="${subjectURL(p,{period:month()})}">${sections[p]}</a>`).join('')}</div>`;
 return out;
}
function history(r){return`<section class="card"><h2>Riwayat versi & pemeriksaan</h2><p class="help">Versi sebelumnya tetap tersimpan. Waktu ditampilkan dalam WIB.</p>${r.versions.map(v=>`<details><summary>Versi ${v.number} · ${esc(v.status)} · ${stamp(v.created_at)}</summary><p class="help">${esc(profile(v.actor_id)?.display_name||'Pemeriksa terdahulu')} · ${esc(v.action)}</p><pre>${esc(JSON.stringify(v.data,null,2))}</pre></details>`).join('')}${r.checks.map(c=>`<details><summary>${esc(c.kind)} · ${stamp(c.created_at)}</summary><p>${esc(profile(c.actor_id)?.display_name||'Pemeriksa terdahulu')}</p><pre>${esc(JSON.stringify(c.data,null,2))}</pre></details>`).join('')}</section>`;}
function facts(data,entries){return`<dl>${entries.map(([k,l])=>`<div class="detail-pair"><dt>${esc(l)}</dt><dd>${esc(data?.[k]??'—')}</dd></div>`).join('')}</dl>`;}
function recordHead(r){const v=latest(r);return`<div class="pill-row">${badge(r.latest_status||v?.status||'Draft')}${badge('Versi '+(v?.number||0))}${badge('M'+r.month_no)}</div><p class="help">${stamp(v?.created_at)} · ${esc(profile(r.mentee_id)?.display_name||'Mentee')}</p>`;}
function recordsList(kind){const records=w.records.filter(r=>r.kind===kind);return records.map(r=>{const v=latest(r),d=v?.data||{},cs=lastCheck(r,'commitment')?.data.status||'Belum diperiksa';return`<article class="record-row" data-search="${esc((d.activity+' '+d.action+' '+v?.status).toLowerCase())}" data-activity="${esc(d.activity)}" data-status="${esc(r.latest_status||v?.status)}"><div class="record-main"><h3>${esc(kind==='abc'?d.activity||'Kegiatan belum dipilih':sections[kind]||kind)}</h3><p>${kind==='abc'?day(d.activityDate):'M'+r.month_no} · ${stamp(v?.created_at)}</p>${kind==='abc'?`<p>${esc(d.action||'Komitmen belum diisi')}</p><p>Tenggat: ${day(d.deadline)}</p>`:''}<div class="badges">${badge(r.latest_status||v?.status)}${kind==='abc'?badge(cs):''}</div></div>${link('Buka',subjectURL(kind==='abc'?'abc':'progres',{record:r.id,period:PERIODS.includes(r.month_no)?r.month_no:month()}))}</article>`;}).join('');}
function abc(){const r=w.records.find(r=>r.id===query.get('record')&&r.kind==='abc');if(editor?.kind==='abc')return abcForm(editor);if(r)return abcDetail(r);
 return title('Worksheet ABC','Refleksi singkat setelah kegiatan. Perkembangan dibuktikan lewat tindakan dan hasil.',owns()?button('Buat ABC baru','data-new="abc"'):'')+`<section class="card"><div class="filters"><label>Cari catatan<input id="abc-search" type="search" placeholder="Kegiatan atau komitmen"></label>${select('activity-filter','Kegiatan',ACTIVITIES)}${select('status-filter','Status catatan',['Draft','Diajukan','Perlu perbaikan','Sudah diperiksa'])}</div><div id="abc-list">${recordsList('abc')||'<p class="sub">Belum ada catatan ABC. Mentee dapat mulai setelah Kick-off, meskipun POC belum tersedia.</p>'}</div><p id="no-results" hidden>Tidak ada catatan yang cocok.</p></section>`;
}
function menteeIdentity(){const e=w.enrolments.find(e=>e.user_id===w.selectedMentee&&e.role==='mentee');return`<p class="help">${esc(profile(w.selectedMentee)?.display_name)} · ${esc(e?.field||'Bidang belum ditetapkan')} · ${esc(e?.pathway||'Pathway belum ditetapkan')}</p>`;}
function formActions(kind,id){return`<div class="actions">${button('Simpan draft','data-record-action="save"')}${button('Ajukan','data-record-action="submit"',true)}${button('Batal','data-cancel',true)}</div><p class="help">Draft boleh belum lengkap. Pengajuan menyimpan versi baru dan tersedia bagi pendamping sesuai penugasan. Tidak ada email otomatis.</p>`;}
function abcForm(ed){const d=ed.data||{},pending=w.records.filter(r=>r.kind==='abc'&&r.id!==ed.id&&!lastCheck(r,'commitment'));return title(ed.id?'Perbaiki ABC':'Buat ABC baru','Maksimal tiga kalimat per bagian refleksi. Jawaban tidak dipotong otomatis.')+`<section class="card">${menteeIdentity()}${pending.length?'<div class="notice warn">Ada komitmen sebelumnya yang belum diperiksa. Kamu tetap dapat menyimpan refleksi kegiatan baru.</div>':''}<form id="record-form" data-kind="abc" data-id="${ed.id||''}" data-month="${ed.month??currentM()}"><div class="field-grid">${select('activity','Kegiatan',ACTIVITIES,d.activity)}${field('activityDate','Tanggal kegiatan',d.activityDate||'','date','Waktu program mengikuti Asia/Jakarta.')}</div>${select('pocRef','Referensi POC (opsional)',w.records.filter(r=>r.kind==='poc').flatMap(r=>r.versions.filter(v=>v.status==='Disepakati').map(v=>[v.id,'POC versi '+v.number+' · '+v.data.title])),d.pocRef,'Tautan konteks. ABC tidak mengubah target POC.')}<section class="form-section"><h3>A — Awareness</h3>${field('awareness','Apa yang saya pahami?',d.awareness,'textarea','Apa yang saya sadari tentang diri, pekerjaan, masalah, atau cara kerja saya? Fakta atau pengalaman apa yang mendasarinya?')}</section><section class="form-section"><h3>B — Best Step</h3>${field('bestStep','Apa satu langkah terbaik berikutnya?',d.bestStep,'textarea','Langkah apa yang paling membantu pengembangan saya, dan mengapa langkah ini yang dipilih? Pilih satu langkah yang jelas.')}</section><section class="form-section"><h3>C — Commitment</h3>${field('action','Tindakan yang akan dikerjakan',d.action,'textarea')}${field('deadline','Tenggat',d.deadline,'date')}${field('evidencePlan','Bukti yang akan dibawa',d.evidencePlan,'textarea','Ini rencana bukti. Bukti hasil aktual dicatat saat tindak lanjut.')}${field('support','Dukungan yang diperlukan: dari siapa dan untuk apa',d.support,'textarea','Boleh menulis Tidak ada.')}</section><section id="kickoff-priorities" class="form-section" ${d.activity==='Kick-off'?'':'hidden'}><h3>Tiga Prioritas Belajar Pribadi</h3><p class="help">Wajib lengkap sebelum ABC Kick-off diajukan.</p>${[0,1,2].map(i=>`<div class="kpi"><h3>Prioritas ${i+1}</h3>${field(`priorities.${i}.ability`,'Kemampuan yang ingin dikembangkan',d.priorities?.[i]?.ability)}${field(`priorities.${i}.why`,'Mengapa penting',d.priorities?.[i]?.why,'textarea')}${field(`priorities.${i}.practice`,'Cara melatihnya',d.priorities?.[i]?.practice,'textarea')}</div>`).join('')}</section><div id="activity-guide" class="notice"></div>${formActions('abc',ed.id)}</form></section>`;}
function abcDetail(r){const v=latest(r),d=v?.data||{},c=lastCheck(r,'commitment');return title(d.activity||'ABC',day(d.activityDate),link('Kembali ke daftar',subjectURL('abc')))+`<section class="card">${recordHead(r)}${facts(d,[['awareness','A — Apa yang saya pahami?'],['bestStep','B — Satu langkah terbaik berikutnya'],['action','C — Tindakan komitmen'],['deadline','Tenggat'],['evidencePlan','Rencana bukti'],['support','Dukungan']])}${d.activity==='Kick-off'?`<h3 style="margin-top:20px">Prioritas belajar</h3>${(d.priorities||[]).map((p,i)=>facts(p,[['ability','Prioritas '+(i+1)],['why','Mengapa penting'],['practice','Cara melatih']])).join('')}`:''}<div class="actions">${owns()?button('Perbaiki / lanjutkan draft',`data-edit="${r.id}"`):''}${button('Salin teks ABC',`data-copy="${r.id}"`,true)}</div></section>${assigned('asmen')&&role==='asmen'&&r.latest_status==='Diajukan'?checkForm(r,'abc_check','Pemeriksaan kelengkapan ABC',`${field('note','Catatan pemeriksaan','','textarea','Asmen memeriksa kelengkapan dan kejelasan. Jawaban mentee tetap utuh.')}${field('repair','Minta perbaikan',false,'checkbox')}`):''}<section class="card"><h2>Tindak lanjut komitmen</h2><p class="help">Merujuk tindakan: ${esc(d.action||'Belum diisi')} · Tenggat ${day(d.deadline)}</p>${c?`${badge(c.data.status)}${facts(c.data,[['action','Tindakan yang benar-benar dijalankan'],['result','Hasil aktual'],['proofUrl','Tautan bukti aktual'],['learning','Pembelajaran atau hambatan'],['next','Langkah berikutnya'],['note','Catatan pemeriksa']])}<p class="help">${esc(profile(c.actor_id)?.display_name||'Asmen')} · ${stamp(c.created_at)}</p>`:'<p class="sub">Belum diperiksa bersama Asmen.</p>'}</section>${assigned('asmen')&&role==='asmen'&&r.latest_status!=='Draft'?checkForm(r,'commitment','Catat pemeriksaan bersama mentee',`${select('status','Status komitmen',['Belum dijalankan','Sedang dijalankan','Selesai','Perlu dukungan'],c?.data.status)}${field('action','Tindakan yang benar-benar dijalankan',c?.data.action,'textarea')}${field('result','Hasil aktual dan bukti',c?.data.result,'textarea')}${field('proofUrl','Tautan bukti hasil aktual',c?.data.proofUrl,'url')}${field('learning','Pembelajaran atau hambatan',c?.data.learning,'textarea')}${field('next','Langkah berikutnya',c?.data.next,'textarea')}${field('note','Catatan pemeriksa',c?.data.note,'textarea')}`):''}${history(r)}`;}
function checkForm(r,action,heading,fields){return`<section class="card"><h2>${esc(heading)}</h2><form data-check="${action}" data-id="${r.id}" data-kind="${r.kind}" data-month="${r.month_no}">${fields}<div class="actions">${button('Simpan pemeriksaan','data-save-check')}</div><p class="help">Pemeriksa dan waktu dicatat dari akun yang masuk. Pemeriksaan sebelumnya tetap ada dalam riwayat.</p></form></section>`;}
function poc(){if(editor?.kind==='poc')return pocForm(editor);const r=w.records.find(r=>r.kind==='poc'),v=latest(r),d=v?.data;if(!r)return title(sections.poc,'Arah, target, dan bukti yang disepakati bersama Mentor.')+empty('POC belum dibuat','ABC tetap dapat diisi, termasuk saat Kick-off.',owns()?button('Buat POC','data-new="poc"'):'');
 return title(sections.poc,d?.title||'POC belum lengkap',owns()?button('Perbaiki / ajukan versi baru',`data-edit="${r.id}"`):'')+`<section class="card">${recordHead(r)}${facts(d,[['outcome','Outcome'],['baselineContext','Kondisi awal'],['risk','Risiko'],['support','Dukungan'],['plan','Rencana kerja']])}${(d?.kpis||[]).map((k,i)=>`<div class="kpi"><h3>KPI ${i+1} · ${esc(k.title)}</h3><p class="help">Baseline: ${esc(k.baseline)} ${esc(k.unit)} · ${k.kind==='number'?(k.direction==='up'?'Semakin tinggi semakin baik':'Semakin rendah semakin baik'):'Milestone'}</p><div class="table-scroll"><table><thead><tr><th>Review</th><th>Progress · 2</th><th>Achieve · 3</th><th>Exceed · 4</th></tr></thead><tbody>${PERIODS.map(m=>`<tr><td>M${m}</td><td>${esc(k.levels?.['M'+m]?.progress)}</td><td>${esc(k.levels?.['M'+m]?.achieve)}</td><td>${esc(k.levels?.['M'+m]?.exceed)}</td></tr>`).join('')}</tbody></table></div><p class="help">Not Achieved · 0: belum memenuhi batas Progress atau klaim belum dapat diverifikasi. ${esc(k.measurement)} · Rencana bukti: ${esc(k.evidencePlan)}</p></div>`).join('')}</section>${assigned('mentor')&&role==='mentor'&&r.latest_status==='Diajukan'?checkForm(r,'poc_decide','Kesepakatan POC oleh Mentor',field('note','Catatan kesepakatan / perbaikan','','textarea')+field('repair','Minta perbaikan sebelum disepakati',false,'checkbox')):''}${history(r)}`;}
function pocForm(ed){const d=ed.data||{},kpis=d.kpis||[{id:crypto.randomUUID()}];return title('Susun Personal Outcome Contract','Satu hingga tiga KPI. Patokan tiap periode ditetapkan bersama Mentor, sebelum dipakai untuk menilai.')+`<section class="card">${menteeIdentity()}<form id="record-form" data-kind="poc" data-id="${ed.id||''}" data-month="1">${field('title','Judul POC',d.title)}${field('outcome','Outcome yang ingin diwujudkan',d.outcome,'textarea')}${field('baselineContext','Kondisi awal dan fakta baseline',d.baselineContext,'textarea')}${kpis.map((k,i)=>`<section class="kpi"><h3>KPI ${i+1}</h3>${hidden(`kpis.${i}.id`,k.id)}${field(`kpis.${i}.title`,'Nama KPI',k.title)}<div class="field-grid">${select(`kpis.${i}.kind`,'Jenis KPI',[['number','Angka'],['milestone','Milestone / kriteria']],k.kind||'number')}${select(`kpis.${i}.direction`,'Arah perubahan',[['up','Semakin tinggi semakin baik'],['down','Semakin rendah semakin baik']],k.direction||'up')}</div><div class="field-grid">${field(`kpis.${i}.baseline`,'Baseline (angka / kriteria awal)',k.baseline)}${field(`kpis.${i}.unit`,'Satuan / ukuran',k.unit)}</div>${field(`kpis.${i}.measurement`,'Cara mengukur dan sumber data',k.measurement,'textarea')}${field(`kpis.${i}.evidencePlan`,'Rencana bukti',k.evidencePlan,'textarea')}<div class="table-scroll"><table><thead><tr><th>Periode</th><th>Progress · 2</th><th>Achieve · 3</th><th>Exceed · 4</th></tr></thead><tbody>${PERIODS.map(m=>`<tr><th>M${m}</th>${['progress','achieve','exceed'].map(key=>`<td><input aria-label="KPI ${i+1} M${m} ${key}" name="kpis.${i}.levels.M${m}.${key}" value="${esc(k.levels?.['M'+m]?.[key])}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="help">Angka: isi batas minimal (atau maksimal jika menurun). Milestone: isi kriteria nyata tiap level. Not Achieved · 0 berlaku ketika batas Progress belum terpenuhi atau klaim belum terverifikasi.</p>${kpis.length>1?button('Hapus KPI ini',`data-remove-kpi="${i}"`,true):''}</section>`).join('')}${kpis.length<3?`<div class="actions">${button('Tambah KPI','data-add-kpi',true)}</div>`:''}${field('risk','Risiko dan antisipasi',d.risk,'textarea')}${field('support','Dukungan yang diperlukan',d.support,'textarea')}${field('plan','Rencana kerja bertahap',d.plan,'textarea')}${agreed(w.records)?field('confirmAmendment','Saya mengajukan perubahan POC sebagai versi baru untuk disepakati ulang oleh Mentor.',false,'checkbox'):''}${formActions('poc',ed.id)}</form></section>`;}
function periods(selected=month()){return`<div class="subject-tabs" aria-label="Periode review">${PERIODS.map(m=>link('M'+m,subjectURL(page==='penilaian'?'review':page,{period:m}),m===selected?'button':'secondary')).join('')}</div>`;}
function progress(){if(editor&&['checkin','mentoring','actual','portfolio'].includes(editor.kind))return progressForm(editor);const r=w.records.find(r=>r.id===query.get('record'));if(r&&['checkin','mentoring','actual','portfolio'].includes(r.kind))return progressDetail(r);
 const m=month(),poc=agreed(w.records),sessions=w.sessions.filter(s=>s.participant_ids.includes(w.selectedMentee));
 return title('Progres & bukti','Mentee menulis tindakan dan hasil aktual. Asmen memeriksa proses serta bukti; Mentor menilai capaian.')+`<div class="flow"><span>1 · Tindakan & bukti dari mentee</span><span>2 · Pemeriksaan Asmen</span><span>3 · Review capaian oleh Mentor</span></div><section class="card"><h2>Perjalanan 12 bulan</h2><div class="month-grid" style="margin-top:16px">${Array.from({length:12},(_,i)=>i+1).map(n=>`<a href="${subjectURL('progres',{month:n,period:PERIODS.includes(n)?n:m})}" class="${Number(query.get('month')||currentM())===n?'current':''}">M${n}<small>${n===1?'Susun POC':PERIODS.includes(n)?'Proses + review':'Proses'}</small></a>`).join('')}</div></section><section class="card"><h2>Check-in & mentoring · M${Number(query.get('month')||currentM())}</h2><p class="help">Jadwal dibuat oleh pengelola. Satu laporan untuk setiap sesi yang diikuti.</p>${sessions.filter(s=>s.month_no===Number(query.get('month')||currentM())).map(s=>{const r=w.records.find(r=>r.session_id===s.id),c=lastCheck(r,'process');return`<div class="record-row"><div class="record-main"><h3>${s.kind==='checkin'?'Check-in bersama Asmen':'Mentoring bulanan'}</h3><p>${stamp(s.starts_at)}</p><div class="badges">${badge(s.cancelled?'Dibatalkan':r?.latest_status||'Belum ada laporan')}${c?badge(c.data.color,c.data.color):''}</div>${s.cancelled?`<p>${esc(s.cancellation_reason)}</p>`:''}</div>${r?link('Buka laporan',subjectURL('progres',{record:r.id})):owns()&&!s.cancelled?button('Isi laporan',`data-session="${s.id}"`):''}</div>`;}).join('')||'<p class="sub">Belum ada jadwal untuk bulan ini. Hubungi pengelola program.</p>'}</section>${periods(m)}<section class="card"><h2>Aktual KPI · M${m}</h2><p class="sub">${poc?'Isi hasil yang benar-benar terjadi. Bukti rencana POC terpisah dari bukti hasil aktual.':'Menunggu POC disepakati Mentor. ABC tetap dapat diisi.'}</p>${(()=>{const r=w.records.find(r=>r.kind==='actual'&&r.month_no===m);return`<div class="actions">${r?link('Buka aktual KPI',subjectURL('progres',{record:r.id,period:m})):owns()&&poc?button('Isi aktual KPI',`data-new="actual" data-period="${m}"`):''}${link('Buka penilaian M'+m,subjectURL('review',{period:m}))}</div>`;})()}</section>${m===12?`<section class="card"><h2>Portofolio akhir & rencana lanjutan</h2><p class="sub">Ringkas perubahan yang terbukti dan langkah 12 bulan berikutnya.</p><div class="actions">${(()=>{const r=w.records.find(r=>r.kind==='portfolio');return r?link('Buka portofolio',subjectURL('progres',{record:r.id,period:12})):owns()?button('Isi portofolio','data-new="portfolio" data-period="12"'):'';})()}</div></section>`:''}`;
}
function abcReference(d){return select('abcRef','Gunakan konteks dari ABC (opsional)',w.records.filter(r=>r.kind==='abc'&&latest(r)?.status!=='Draft').map(r=>[r.id,(latest(r).data.activity||'ABC')+' · '+day(latest(r).data.activityDate)]),d.abcRef,'Memilih ABC hanya menautkan konteks; isi tindakan dan hasil kegiatan ini tetap perlu ditulis.');}
function progressForm(ed){const d=ed.data||{},kind=ed.kind,poc=agreed(w.records),m=ed.month||month();let fields='';
 if(kind==='checkin')fields=abcReference(d)+field('action','Tindakan yang benar-benar dijalankan',d.action,'textarea')+field('result','Hasil aktual',d.result,'textarea')+field('proofText','Bukti hasil / penjelasan jika belum ada',d.proofText,'textarea')+field('proofUrl','Tautan bukti aktual (opsional)',d.proofUrl,'url')+field('learning','Pembelajaran atau hambatan',d.learning,'textarea')+field('next','Langkah berikutnya',d.next,'textarea')+field('deadline','Tenggat langkah berikutnya',d.deadline,'date');
 if(kind==='mentoring')fields=abcReference(d)+[['priority','Prioritas yang dibahas'],['insight','Pembelajaran dari percakapan'],['decision','Keputusan bersama Mentor'],['action','Tindakan berikutnya'],['evidencePlan','Bukti yang akan dibawa']].map(([k,l])=>field(k,l,d[k],'textarea')).join('')+field('deadline','Tenggat',d.deadline,'date');
 if(kind==='actual')fields=hidden('pocVersion',poc?.id||'')+`<div class="notice">Mengacu POC versi ${poc?.number||'—'}. Kosong tidak dianggap nol. Jika bukti belum ada, nyatakan dengan jujur.</div>`+(poc?.data.kpis||[]).map((k,i)=>{const it=d.items?.find(x=>x.kpiId===k.id)||{};return`<section class="kpi"><h3>${esc(k.title)}</h3><p class="help">Baseline ${esc(k.baseline)} ${esc(k.unit)} · Target M${m}: ${esc(k.levels?.['M'+m]?.achieve)} · Exceed: ${esc(k.levels?.['M'+m]?.exceed)}</p>${hidden(`items.${i}.kpiId`,k.id)}${field(`items.${i}.value`,'Hasil aktual ('+k.unit+')',it.value,k.kind==='number'?'number':'textarea','','step="any"')}${field(`items.${i}.summary`,'Penjelasan hasil dan cara pengukuran',it.summary,'textarea')}${field(`items.${i}.proofText`,'Bukti hasil aktual',it.proofText,'textarea')}${field(`items.${i}.proofUrl`,'Tautan bukti (opsional)',it.proofUrl,'url')}${field(`items.${i}.noEvidence`,'Bukti outcome belum tersedia / belum dapat dibawa.',it.noEvidence,'checkbox')}</section>`;}).join('')+field('learning','Pembelajaran utama',d.learning,'textarea')+field('next','Langkah berikutnya',d.next,'textarea');
 if(kind==='portfolio')fields=field('summary','Perubahan yang dapat dibuktikan',d.summary,'textarea')+field('proof','Ringkasan bukti dan hasil akhir',d.proof,'textarea')+field('proofUrl','Tautan portofolio (opsional)',d.proofUrl,'url')+field('plan','Langkah untuk 12 bulan berikutnya',d.plan,'textarea');
 return title(({checkin:'Laporan check-in',mentoring:'Catatan mentoring',actual:'Aktual KPI',portfolio:'Portofolio akhir'})[kind]+' · M'+m,'Mentee mengisi jawaban sendiri. Pemeriksa memberi catatan melalui bagian yang terpisah.')+`<section class="card">${menteeIdentity()}<form id="record-form" data-kind="${kind}" data-id="${ed.id||''}" data-month="${m}" data-session="${ed.session||''}">${fields}${formActions(kind,ed.id)}</form></section>`;
}
function progressDetail(r){const v=latest(r),d=v?.data||{},poc=agreed(w.records),process=lastCheck(r,'process'),ev=lastCheck(r,'evidence');let content='';
 if(r.kind==='checkin')content=facts(d,[['action','Tindakan aktual'],['result','Hasil aktual'],['proofText','Bukti hasil'],['proofUrl','Tautan bukti'],['learning','Pembelajaran / hambatan'],['next','Langkah berikutnya'],['deadline','Tenggat']]);
 if(r.kind==='mentoring')content=facts(d,[['priority','Prioritas'],['insight','Pembelajaran'],['decision','Keputusan'],['action','Tindakan'],['evidencePlan','Rencana bukti'],['deadline','Tenggat']]);
 if(r.kind==='actual')content=(d.items||[]).map(it=>`<div class="kpi"><h3>${esc(poc?.data.kpis.find(k=>k.id===it.kpiId)?.title||'KPI dari versi POC sebelumnya')}</h3>${facts(it,[['value','Aktual'],['summary','Penjelasan hasil'],['proofText','Bukti aktual'],['proofUrl','Tautan bukti']])}${it.noEvidence?'<p class="notice warn">Bukti outcome belum tersedia.</p>':''}</div>`).join('')+facts(d,[['learning','Pembelajaran'],['next','Langkah berikutnya']]);
 if(r.kind==='portfolio')content=facts(d,[['summary','Perubahan terbukti'],['proof','Bukti hasil akhir'],['proofUrl','Tautan portofolio'],['plan','Rencana 12 bulan berikutnya']]);
 let checks='';if(role==='asmen'&&assigned('asmen')&&r.latest_status!=='Draft'){
  if(r.kind==='checkin')checks=checkForm(r,'process','Pemeriksaan proses oleh Asmen',`<div class="notice">Green: tindakan dan bukti memadai. Yellow: ada perkembangan tetapi perlu perbaikan. Red: belum ada tindakan/bukti yang memadai atau dua Yellow berturut-turut tanpa perbaikan yang dikonfirmasi Asmen. Status ini bukan level capaian KPI.</div>${select('color','Status proses',['Green','Yellow','Red'],process?.data.color)}${field('actionChecked','Saya sudah memeriksa tindakan yang dijalankan.',process?.data.actionChecked,'checkbox')}${field('evidenceChecked','Saya sudah memeriksa bukti hasil aktual.',process?.data.evidenceChecked,'checkbox')}${field('noImprovement','Jika Yellow berulang: belum ada perbaikan dari check-in sebelumnya.',false,'checkbox')}${field('note','Catatan dan alasan status',process?.data.note,'textarea')}`);
  if(r.kind==='actual'&&poc)checks=checkForm(r,'evidence','Pemeriksaan bukti aktual oleh Asmen',`<p class="help">Pilih bukti terkuat yang telah diperiksa untuk setiap KPI. Banyaknya tautan tidak menambah nilai.</p>${poc.data.kpis.map((k,i)=>{const e=ev?.data.items.find(x=>x.kpiId===k.id)||{};return`<div class="kpi"><h3>${esc(k.title)}</h3>${hidden(`items.${i}.kpiId`,k.id)}${select(`items.${i}.tier`,'Kekuatan bukti',[[0,'0 · Aktivitas / belum ada bukti hasil'],[1,'1 · Output tersedia'],[2,'2 · Mutu output terbukti'],[3,'3 · Outcome terbukti'],[4,'4 · Dampak berkelanjutan']],e.tier,'','data-number')}${field(`items.${i}.verified`,'Bukti ini sudah saya periksa dan dapat diverifikasi.',e.verified,'checkbox')}${field(`items.${i}.note`,'Catatan dan alasan pemeriksaan',e.note,'textarea')}</div>`;}).join('')}`);
 }
 if(role==='mentor'&&assigned('mentor')&&r.kind==='mentoring'&&r.latest_status==='Diajukan')checks=checkForm(r,'mentoring_check','Konfirmasi catatan mentoring',field('note','Catatan Mentor','','textarea')+field('repair','Minta perbaikan catatan',false,'checkbox'));
 return title(({checkin:'Laporan check-in',mentoring:'Catatan mentoring',actual:'Aktual KPI',portfolio:'Portofolio akhir'})[r.kind]+' · M'+r.month_no,'',link('Kembali ke progres',subjectURL('progres',{period:PERIODS.includes(r.month_no)?r.month_no:month(),month:r.month_no})))+`<section class="card">${recordHead(r)}${process?`<p style="margin-top:10px">${badge(process.data.color,process.data.color)} ${esc(process.data.note)}</p>`:''}${ev?`<p class="notice success">Bukti sudah diperiksa Asmen pada ${stamp(ev.created_at)}. Penetapan level capaian tetap melalui Mentor / Tim Penilaian.</p>`:''}${content}${owns()?`<div class="actions">${button('Perbaiki / buat versi baru',`data-edit="${r.id}"`)}</div>`:''}</section>${checks}${history(r)}`;
}
function review(){const m=month(),can=(m===12?role==='program'&&assessor():role==='mentor'&&assigned('mentor')),r=w.records.find(r=>r.kind==='review'&&r.month_no===m),v=latest(r),poc=agreed(w.records),actual=w.records.find(r=>r.kind==='actual'&&r.month_no===m),av=latest(actual),ev=lastCheck(actual,'evidence'),d=v?.data||{},pub=r?.publications.at(-1);
 let out=title('Penilaian mentee · M'+m,'Baca sumber, bandingkan dengan patokan POC, lalu catat keputusan beserta alasannya.')+periods(m)+`<div class="flow"><span>1 · POC disepakati</span><span>2 · Aktual diajukan</span><span>3 · Bukti diperiksa Asmen</span><span>4 · Penilai menetapkan capaian</span></div><div class="grid"><section class="card"><h2>Sumber penilaian</h2><dl>${[['POC',poc?'Versi '+poc.number+' · Disepakati':'Belum disepakati'],['Aktual KPI',av?.status==='Diajukan'?'Versi '+av.number+' · Diajukan':'Belum diajukan'],['Pemeriksaan bukti',ev?'Sudah diperiksa Asmen':'Belum diperiksa']].map(([a,b])=>`<div class="detail-pair"><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><div class="actions">${link('Baca POC',subjectURL('poc'))}${actual?link('Baca aktual & bukti',subjectURL('progres',{record:actual.id,period:m})):link('Buka progres',subjectURL('progres',{period:m}))}</div></section><section class="card"><h2>Yang dinilai</h2><p class="sub">P1 Proses · 25<br>P2 Capaian KPI · 25<br>${m===3?'P3 belum dinilai pada M3':m===9?'P3 Kepemimpinan memakai hasil M6 · 25':'P3 Kepemimpinan · 25'}<br>P4 Kekuatan bukti · 25</p><p class="help">${m===3?'M3 dinormalisasi: (P1 + P2 + P4) × 100 / 75.':'Total = P1 + P2 + P3 + P4.'} ABC tidak diberi skor. Green/Yellow/Red hanya untuk proses.</p></section></div>`;
 if(pub)out+=publicationCard(pub,m);
 if(!can)return out+(!pub?empty('Penilaian belum diterbitkan',m===12?'Tim Penilaian yang ditugaskan menetapkan hasil akhir.':'Mentor menetapkan level capaian setelah sumber dan pemeriksaan lengkap.'):'');
 if(!poc||!av||av.status!=='Diajukan'||!ev)return out+empty('Sumber belum lengkap','Minta mentee mengajukan aktual dan Asmen memeriksa bukti sebelum melakukan penilaian.');
 const stale=!!v&&(d.pocVersion!==poc.id||d.actualVersion!==av.id||d.evidenceCheck!==ev.id||!!d.sourceSnapshot&&d.sourceSnapshot!==sourceSnapshot(w,m)||[6,12].includes(m)&&(d.observerRefs||[]).some(ref=>!observerState?.feedback?.some(f=>f.version===ref)));
 out+=`<section class="card"><h2>${m===12?'Penetapan hasil akhir oleh Tim Penilaian':'Penetapan capaian oleh Mentor'}</h2>${stale?'<div class="notice warn">Sumber berubah sejak penilaian terakhir. Periksa ulang semua keputusan sebelum menerbitkan versi berikutnya.</div>':''}<form id="review-form" data-id="${r?.id||''}" data-month="${m}">${hidden('sourceSnapshot',sourceSnapshot(w,m))}${hidden('pocVersion',poc.id)}${hidden('actualVersion',av.id)}${hidden('evidenceCheck',ev.id)}${poc.data.kpis.map((k,i)=>{const a=av.data.items.find(a=>a.kpiId===k.id)||{},item=d.items?.find(x=>x.kpiId===k.id)||{},e=ev.data.items.find(e=>e.kpiId===k.id)||{};return`<section class="kpi"><h3>${esc(k.title)}</h3><p class="sub">Aktual: <strong>${a.value===''?'Belum diisi':esc(a.value)} ${esc(k.unit)}</strong> · ${esc(a.summary)}</p><p class="help">Bukti Asmen: tingkat ${e.tier} · ${e.verified?'Terverifikasi':'Belum terverifikasi'} · ${esc(e.note)}</p><div class="table-scroll"><table><tr><th>Not Achieved · 0</th><th>Progress · 2</th><th>Achieve · 3</th><th>Exceed · 4</th></tr><tr><td>Di bawah Progress / klaim belum terverifikasi</td>${['progress','achieve','exceed'].map(key=>`<td>${esc(k.levels['M'+m][key])}</td>`).join('')}</tr></table></div>${hidden(`items.${i}.kpiId`,k.id)}${select(`items.${i}.level`,'Level yang ditetapkan',LEVELS,stale?'':item.level)}${field(`items.${i}.reason`,'Alasan penetapan berdasarkan hasil dan bukti',item.reason,'textarea')}${field(`items.${i}.confirmed`,'Saya telah membandingkan aktual dan bukti dengan patokan POC.',stale?false:item.confirmed,'checkbox')}</section>`;}).join('')}${[6,12].includes(m)?`<section class="form-section"><h3>Kepemimpinan · enam kompetensi</h3><p class="help">1: perlu arahan intensif · 2: mulai menerapkan dengan pendampingan · 3: mandiri dan konsisten · 4: memberi dampak serta menjadi rujukan. Nilai tidak muncul sebelum keenamnya lengkap.</p>${COMPETENCIES.map((c,i)=>`<div class="kpi"><h3>${esc(c)}</h3>${observerPanel(observerState,i)}${select(`leadership.${i}.level`,'Level',[[1,'1 · Perlu arahan intensif'],[2,'2 · Menerapkan dengan pendampingan'],[3,'3 · Mandiri dan konsisten'],[4,'4 · Berdampak dan menjadi rujukan']],d.leadership?.[i]?.level,'','data-number')}${field(`leadership.${i}.note`,'Perilaku yang diamati dan alasan level',d.leadership?.[i]?.note,'textarea')}${field(`leadership.${i}.proofUrl`,'Tautan bukti kepemimpinan',d.leadership?.[i]?.proofUrl,'url')}</div>`).join('')}</section>`:m===9?'<div class="notice">Kepemimpinan M9 memakai nilai dari publikasi M6. Tidak dinilai ulang pada periode ini.</div>':''}${[6,12].includes(m)?observerSelection(observerState,d.observerRefs||[]):''}${field('next','Arahan dan langkah pendampingan berikutnya',d.next,'textarea')}<div class="actions">${button('Simpan draft penilaian','data-review-save')}${button(pub?'Terbitkan versi penilaian baru':'Periksa & terbitkan penilaian','data-publish',true)}</div><p class="help">Publikasi menghitung nilai di server, memeriksa kelengkapan sumber, dan menyimpan salinan sumber serta versi aturan. Versi sebelumnya tetap tersedia. Tidak ada email otomatis.</p></form></section>${r?history(r):''}`;return out;
}
function publicationCard(pub,m){const s=pub.score;return`<section class="card"><div class="page-title"><div><h2>Hasil review M${m}</h2><p class="help">Diterbitkan ${stamp(pub.created_at)} · ${esc(profile(pub.actor_id)?.display_name||'Penilai yang ditugaskan')}</p></div><strong class="report-score">${number(s.total)}<small style="font:14px 'Plus Jakarta Sans'"> / 100</small></strong></div><div class="grid" style="grid-template-columns:repeat(4,minmax(0,1fr));gap:8px">${[['p1','Proses'],['p2','Capaian'],['p3','Kepemimpinan'],['p4','Bukti']].map(([k,l])=>`<div><small>${l}</small><h3>${s.components[k]===null?'Tidak dinilai':number(s.components[k])}</h3></div>`).join('')}</div><p class="help">${esc(s.formula)} · ${esc(s.rule)}</p><details><summary>Dasar perhitungan dan sumber</summary><pre>${esc(JSON.stringify({nilai:s,sumber:pub.sources},null,2))}</pre></details></section>`;}
function report(){const pubs=w.records.filter(r=>r.kind==='review').flatMap(r=>r.publications.map(p=>({...p,month:r.month_no}))).sort((a,b)=>a.month-b.month||a.number-b.number);return title('Raport','Ringkasan hasil yang sudah diterbitkan. Tidak ada peringkat atau aturan kelulusan otomatis.')+(!pubs.length?empty('Raport belum tersedia','Hasil muncul setelah penilai menerbitkan review berdasarkan POC, tindakan, dan bukti.'):PERIODS.map(m=>{const p=pubs.filter(p=>p.month===m).at(-1);return p?publicationCard(p,m):'';}).join(''))+`<section class="card"><h2>Langkah berikutnya</h2><p class="sub">${esc(pubs.at(-1)?w.records.find(r=>r.id===pubs.at(-1).record_id)?.versions.find(v=>v.id===pubs.at(-1).version_id)?.data.next||'Baca arahan bersama pendamping.':'Belum ada arahan dari penilaian yang diterbitkan.')}</p><div class="actions">${link('Lihat progres & bukti',subjectURL('progres'))}${link('Baca ABC',subjectURL('abc'))}</div></section>${pubs.length?`<section class="card"><h2>Riwayat publikasi</h2>${pubs.map(p=>`<details><summary>M${p.month} · Versi ${p.number} · ${stamp(p.created_at)}</summary><p>Nilai ${number(p.score.total)} · ${esc(p.score.rule)}</p></details>`).join('')}</section>`:''}`;}
function groupPage(){return title('Kelompok dampingan','Pilih mentee untuk membaca arah, tindakan, bukti, dan hasil review.')+(!w.groups.length?empty('Belum ada kelompok dampingan','Pengelola perlu menetapkan satu Mentor, satu Asmen, dan lima mentee dalam Bidang yang sama.'):w.groups.map(g=>`<section class="card"><div class="page-title"><div><h2>${esc(g.name)}</h2><p class="help">${esc(g.field)} · ${g.active?'Aktif':'Penugasan belum lengkap'}</p></div>${badge(w.members.filter(m=>m.group_id===g.id&&m.active).length+' / 5 mentee')}</div><p class="help">Mentor: ${esc(profile(g.mentor_id)?.display_name||'Belum ditetapkan')} · Asmen: ${esc(profile(g.asmen_id)?.display_name||'Belum ditetapkan')}</p>${w.members.filter(m=>m.group_id===g.id&&m.active).map(m=>`<div class="record-row"><div class="record-main"><h3>${esc(profile(m.user_id)?.display_name||'Mentee')}</h3><p>${esc(w.enrolments.find(e=>e.user_id===m.user_id&&e.role==='mentee')?.pathway)}</p></div>${link('Buka tinjauan',url('kelompok/progres',{mentee:m.user_id}))}</div>`).join('')||'<p class="sub">Belum ada mentee yang ditugaskan.</p>'}</section>`).join(''));}
const guides={'Kick-off':'Refleksikan sikap, kebiasaan belajar, dan persiapan mengikuti program.','Define the Arena':'Perjelas fokus, penerima manfaat, fakta, asumsi, gap, dan bukti baseline.','Build & Execute':'Periksa kesesuaian outcome, KPI, baseline, dan bagian POC yang perlu diselesaikan.','Mentoring/check-in':'Tinjau hasil tindakan sebelumnya, pembelajaran, dan langkah berikutnya.','Expert Visit':'Wawasan, akses, atau peluang apa yang akan diterapkan? Rangkuman kunjungan saja belum menjadi komitmen.','Coaching Clinic':'Apa hambatan utama, penyebabnya, pilihan solusi, dan rencana ujinya?','Showcase/Graduation':'Perubahan apa yang terbukti? Apa langkah untuk 12 bulan berikutnya?'};
function render(){if(reviewPreview)return renderPreview();announce();let body;if(!me().active)body=empty('Akun belum mendapat akses','Pengelola perlu mengaktifkan akun dan memberikan peran yang sesuai.');else if(!role)body=empty('Menunggu penugasan','Akunmu aktif. Hubungi pengelola untuk penetapan peran.');else if(page==='keuangan')body=empty('Modul keuangan sedang disiapkan','Belum ada data keuangan yang ditampilkan. Akses penilaian mengikuti penugasan lain yang dimiliki akun.');else if(page==='kelompok')body=groupPage();else if(['poc','abc','progres','review','raport','penilaian'].includes(page)){body=permissionsEmpty()||({poc,abc,progres:progress,review,penilaian:review,raport:report}[page])();}else body=empty('Halaman sedang disiapkan','Gunakan menu utama untuk kembali ke ruang program.');
 $('#content').innerHTML=`<div class="breadcrumb">${esc(me().display_name)} · ERP IPB LEAP · ${esc(labels[role]||'Akun')} · ${esc(sections[page]||'Beranda')}</div>${context()}<div id="message" role="status" aria-live="polite"></div>${body}<footer class="footer">IPB LEAP · Penyimpanan melalui layanan IPB LEAP; hanya tindakan yang dikonfirmasi berhasil telah tersimpan. Waktu Asia/Jakarta (WIB). Tidak ada email atau notifikasi otomatis.</footer>`;bind();}
function announce(){window.leapAccount=w.actor;window.leapCohortName=cohort()?.name;window.leapContext={cohort:w.selectedCohort,mentee:w.selectedMentee,group:w.selectedMentee?group()?.id:null,period:month(),source:query.get('record')||query.get('source')};window.dispatchEvent(new CustomEvent('leap:account'));}
async function refresh(){
 const c=query.get('cohort'),p=query.get('mentee');if(c&&p)rev=await revision(c,p);w=await workspace(c||null,p||null);if(!(c&&p)&&w.selectedMentee){rev=await revision(w.selectedCohort,w.selectedMentee);w=await workspace(w.selectedCohort,w.selectedMentee);}role=me().roles.includes(sessionStorage.getItem('ipbleap.ui.role'))?sessionStorage.getItem('ipbleap.ui.role'):me().roles[0];if(!w.selectedMentee)rev=0;try{observerState=await observerWorkspace(w.selectedCohort,w.selectedMentee,month());}catch(e){observerState={available:false,reason:errorText(e),feedback:[]};}render();
}
function editRecord(id){const r=w.records.find(r=>r.id===id);if(!r||!owns())return;editor={id:r.id,kind:r.kind,data:structuredClone(latest(r)?.data||{}),month:r.month_no,session:r.session_id};render();}
function newRecord(kind,session){if(!owns())return;const existing=kind==='abc'?null:w.records.find(r=>r.kind===kind&&(kind==='poc'||r.month_no===(kind==='portfolio'?12:session?.month_no||month()))&&(kind!=='checkin'||r.session_id===session?.id));if(existing){editRecord(existing.id);return;}editor={kind,data:{},month:kind==='poc'?1:kind==='abc'?currentM():kind==='portfolio'?12:session?.month_no||month(),session:session?.id};render();}
async function run(fn,success='Tersimpan.'){if(busy)return;busy=true;document.querySelector('#assessment').querySelectorAll('button').forEach(b=>b.disabled=true);inform('Menyimpan…');try{const result=await fn();dirty=false;editor=null;await refresh();inform(success,'success');return result;}catch(e){inform(errorText(e),'error');}finally{busy=false;document.querySelector('#assessment').querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function sendRecord(form,action){const data=read(form);if(['review_save','publish'].includes(action))data.observerRefs=[...form.querySelectorAll('[data-observer-ref]:checked')].map(el=>el.dataset.observerRef);const id=form.dataset.id||crypto.randomUUID();form.dataset.id=id;if(editor)editor.id=id;const abc=w.records.find(r=>r.id===data.abcRef);if(abc)data.abcVersion=latest(abc)?.id;const payload={action,data,id,kind:form.dataset.kind||'review',month:Number(form.dataset.month),session:form.dataset.session||null,cohort:w.selectedCohort,mentee:w.selectedMentee,expected:rev,request:crypto.randomUUID(),confirmAmendment:data.confirmAmendment===true};delete data.confirmAmendment;
 const signature=JSON.stringify({...payload,request:null});let pending=pendingRequests.get(form);if(pending?.signature===signature)payload.request=pending.request;else pendingRequests.set(form,{signature,request:payload.request});
 await run(()=>recordCommand(payload),action==='submit'?'Catatan diajukan dan tersimpan sebagai versi baru.':action==='publish'?'Penilaian diterbitkan. Sumber dan versi perhitungannya ikut tersimpan.':'Versi baru tersimpan. Versi sebelumnya tetap tersedia.');}
function bind(){
 $('#assessment-role')?.addEventListener('change',e=>{if(dirty&&!confirm('Isian belum disimpan. Ganti akses?'))return;sessionStorage.setItem('ipbleap.ui.role',e.target.value);role=e.target.value;render();});
 $('#cohort-select')?.addEventListener('change',e=>{if(dirty&&!confirm('Isian belum disimpan. Pindah cohort?'))return;location.href=url(route.join('/')||'beranda',{cohort:e.target.value,mentee:null});});
 $('#mentee-select')?.addEventListener('change',e=>{if(dirty&&!confirm('Isian belum disimpan. Pindah mentee?'))return;location.href=url(route.join('/'),{mentee:e.target.value});});
 document.querySelector('#assessment').querySelectorAll('form').forEach(f=>{f.addEventListener('submit',e=>e.preventDefault());f.addEventListener('input',()=>dirty=true);});
 document.querySelector('#assessment').querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>newRecord(b.dataset.new));document.querySelector('#assessment').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editRecord(b.dataset.edit));
 document.querySelector('#assessment').querySelectorAll('[data-session]').forEach(b=>{if(b.tagName!=='BUTTON')return;b.onclick=()=>{const s=w.sessions.find(s=>s.id===b.dataset.session);newRecord(s.kind==='checkin'?'checkin':'mentoring',s);};});
 document.querySelector('#assessment').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{if(dirty&&!confirm('Isian belum disimpan. Tutup formulir?'))return;dirty=false;editor=null;render();});
 document.querySelector('#assessment').querySelectorAll('[data-record-action]').forEach(b=>b.onclick=()=>sendRecord(b.closest('form'),b.dataset.recordAction));
 document.querySelector('#assessment').querySelectorAll('[data-save-check]').forEach(b=>b.onclick=()=>sendRecord(b.closest('form'),b.closest('form').dataset.check));
 $('[data-review-save]')?.addEventListener('click',e=>sendRecord(e.target.closest('form'),'review_save'));
 $('[data-publish]')?.addEventListener('click',e=>{if(confirm('Terbitkan penilaian berdasarkan sumber yang ditampilkan? Nilai akan dihitung dan kelengkapannya diperiksa di server.'))sendRecord(e.target.closest('form'),'publish');});
 $('[data-add-kpi]')?.addEventListener('click',()=>{editor.data=read($('#record-form'));editor.data.kpis.push({id:crypto.randomUUID()});render();dirty=true;});
 document.querySelector('#assessment').querySelectorAll('[data-remove-kpi]').forEach(b=>b.onclick=()=>{if(!confirm('Hapus KPI ini dari isian versi yang sedang dikerjakan? Versi tersimpan sebelumnya tetap ada.'))return;editor.data=read($('#record-form'));editor.data.kpis.splice(Number(b.dataset.removeKpi),1);render();dirty=true;});
 const activity=$('[name=activity]');if(activity){const update=()=>{$('#kickoff-priorities').hidden=activity.value!=='Kick-off';$('#activity-guide').textContent=guides[activity.value]||'Pilih kegiatan untuk melihat pertanyaan bantuan.';};activity.addEventListener('change',update);update();}
 const filter=()=>{const term=$('#abc-search').value.toLowerCase(),act=$('[name=activity-filter]').value,status=$('[name=status-filter]').value;let visible=0;document.querySelector('#assessment').querySelectorAll('#abc-list .record-row').forEach(r=>{r.hidden=!!(term&&!r.dataset.search.includes(term)||act&&r.dataset.activity!==act||status&&r.dataset.status!==status);if(!r.hidden)visible++;});$('#no-results').hidden=visible>0||!w.records.some(r=>r.kind==='abc');};$('#abc-search')?.addEventListener('input',filter);$('[name=activity-filter]')?.addEventListener('change',filter);$('[name=status-filter]')?.addEventListener('change',filter);
 document.querySelector('#assessment').querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const r=w.records.find(r=>r.id===b.dataset.copy),d=latest(r).data,text=['WORKSHEET ABC · IPB LEAP',profile(r.mentee_id)?.display_name,d.activity+' · '+day(d.activityDate),'A — '+(d.awareness||''),'B — '+(d.bestStep||''),'C — '+(d.action||''),'Tenggat: '+(d.deadline||''),'Rencana bukti: '+(d.evidencePlan||''),'Dukungan: '+(d.support||'')].join('\n\n');try{await navigator.clipboard.writeText(text);inform('Teks ABC disalin.','success');}catch{$('#copy-text').value=text;$('#copy-dialog').showModal();}});

}
$('#copy-activation').onclick=async()=>{try{await navigator.clipboard.writeText($('#activation-link').value);$('#copy-activation').textContent='Tautan disalin';}catch{$('#activation-link').select();}};
$('#close-activation').onclick=()=>{$('#activation-link').value='';$('#activation-dialog').close();};
$('#close-copy').onclick=()=>$('#copy-dialog').close();
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function start(){if(!configured)throw Error('Layanan ERP sedang disiapkan.');if(!await verifiedUser()){location.replace(new URL('akses-penilaian.html',appBase).pathname+'?next='+encodeURIComponent(location.pathname+location.search));return;}await bootstrap();await refresh();}
export function mount(){start().catch(e=>{$('#content').innerHTML=empty('Halaman belum dapat dimuat',errorText(e),button('Coba lagi','id="retry"',true)+link('Kembali ke login',new URL('akses-penilaian.html',appBase).pathname));$('#retry')?.addEventListener('click',()=>location.reload());});}

// Appended only to the isolated public review build; excluded from operational assets.
let reviewPreview=false;
function previewReview(){
 const m=role==='program'?12:month();if(m===12&&role!=='program')return title('Penilaian akhir M12','Penetapan akhir merupakan kewenangan Tim Penilaian yang ditugaskan.')+previewSources();return title((role==='program'?'Penilaian akhir oleh Tim Penilaian · M':'Review capaian oleh Mentor · M')+m,'Baca sumber, bandingkan dengan patokan POC, lalu catat keputusan beserta alasannya.')+(role==='program'?'<p class="help">Periode kewenangan: M12</p>':periods(m))+`<div class="flow"><span>POC</span><span>Aktual & bukti</span><span>Pemeriksaan Asmen</span><span>Keputusan penilai</span><span>Raport</span></div><section class="card"><h2>Sumber penilaian</h2><p class="sub">Belum ada cohort, mentee, POC, aktual atau pemeriksaan yang dipilih. Semua nilai tetap kosong.</p></section><section class="card"><h2>P1 · Proses — hasil pemeriksaan Asmen</h2><p class="sub">Belum ada pemeriksaan proses. Penilai membaca hasil Green/Yellow/Red dari Asmen; tidak mengisi ulang warna proses.</p><p class="help">Jumlah poin / (check-in wajib × 3) × 25. Jadwal dan pemeriksaan harus lengkap.</p></section><section class="card"><h2>P2 · Capaian KPI</h2><p class="help">KPI berasal dari POC yang disepakati. Baseline, aktual, batas periode dan bukti ditampilkan di sini setelah sumber tersedia.</p><div class="kpi"><h3>KPI belum dipilih</h3>${select('previewKpi','Level yang ditetapkan',LEVELS)}${field('previewKpiReason','Alasan penetapan berdasarkan hasil dan bukti','','textarea')}${field('previewKpiConfirmed','Saya telah membandingkan aktual dan bukti dengan patokan POC.',false,'checkbox')}</div><p class="help">Not Achieved = 0 · Progress = 2 · Achieve = 3 · Exceed = 4. Jumlah poin / (jumlah KPI × 4) × 25.</p></section>${m===3?'<section class="card"><h2>P3 · Kepemimpinan</h2><p>M3 tidak memuat P3.</p></section>':m===9?'<section class="card"><h2>P3 · Kepemimpinan</h2><p>M9 menggunakan P3 dari publikasi M6. Tidak dinilai ulang.</p></section>':`<section class="card"><h2>P3 · Enam kompetensi kepemimpinan</h2><p class="help">1 · Perlu arahan intensif; 2 · Menerapkan dengan pendampingan; 3 · Mandiri dan konsisten; 4 · Berdampak dan menjadi rujukan.</p>${COMPETENCIES.map((c,i)=>`<div class="kpi"><h3>${esc(c)}</h3><details><summary>Masukan pengamat 360</summary><p>Belum ada masukan. Jenis/jumlah pengamat dan anonimitas menunggu keputusan. Masukan menjadi pertimbangan, tanpa skor tambahan atau rata-rata otomatis.</p></details>${select('previewLeadership'+i,'Level akhir yang ditetapkan penilai',[[1,'1 · Perlu arahan intensif'],[2,'2 · Menerapkan dengan pendampingan'],[3,'3 · Mandiri dan konsisten'],[4,'4 · Berdampak dan menjadi rujukan']])}${field('previewLeadershipReason'+i,'Perilaku yang diamati dan alasan level','','textarea')}${field('previewLeadershipProof'+i,'Tautan bukti kepemimpinan','','url')}</div>`).join('')}</section>`}<section class="card"><h2>P4 · Kekuatan bukti — hasil pemeriksaan Asmen</h2><p class="sub">Belum ada pemeriksaan bukti. Bukti terkuat dan verifikasinya dibaca dari pemeriksaan Asmen; tidak dinilai dua kali.</p><p class="help">Bukti tidak terverifikasi bernilai nol. Banyak tautan tidak menambah nilai.</p></section><section class="card"><h2>Ringkasan review</h2><strong class="report-score">— <small style="font:14px 'Plus Jakarta Sans'">/ 100</small></strong><p class="help">${m===3?'(P1 + P2 + P4) × 100 / 75':'P1 + P2 + P3 + P4'} · ${RULE}. ABC tidak diberi skor.${m===12?' Portofolio akhir wajib diajukan.':''}</p>${field('previewNext','Arahan dan langkah pendampingan berikutnya','','textarea')}<div class="actions"><button class="button" disabled>Simpan draft</button><button class="secondary" disabled>Terbitkan raport</button></div><p class="help">Dinonaktifkan pada preview. Tidak ada penyimpanan, publikasi, email atau notifikasi.</p></section>`;
}
const previewRoleLabels={mentee:'Mentee',asmen:'Asisten Mentor',mentor:'Mentor',program:'Tim Penilaian M12'};
const previewRoles=Object.keys(previewRoleLabels);
function previewHref(file,extra={}){const p=new URLSearchParams({peran:role,period:String(month()),...extra});return file+'.html?'+p;}
function previewSources(kind='Sumber mentee'){
 return `<section class="card"><h2>${esc(kind)}</h2><p class="help">Cohort, kelompok, mentee dan periode mengikuti pilihan dari Kelompok. Belum ada data operasional yang dipilih pada preview.</p><dl>${['POC disepakati','Worksheet ABC','Tindakan & hasil aktual','Bukti aktual','Versi sumber'].map(s=>`<div class="detail-pair"><dt>${s}</dt><dd>— Belum tersedia</dd></div>`).join('')}</dl></section>`;
}
function previewGroup(){
 const tasks=role==='asmen'?[['abc','Periksa ABC','Periksa kelengkapan; minta perbaikan tanpa mengubah jawaban.'],['abc','Tindak lanjut komitmen','Catat pelaksanaan, hasil, hambatan dan dukungan.','komitmen'],['progres','Periksa proses & bukti','Konfirmasi tindakan, warna proses dan kekuatan bukti.'],['raport','Baca raport','Hasil yang sudah diterbitkan penilai.']]:[['poc','Sepakati POC','Samakan outcome, baseline dan patokan dengan mentee.'],['abc','Baca ABC','Pahami refleksi dan komitmen mentee.'],['progres','Baca aktual & bukti','Baca tindakan serta hasil pemeriksaan Asmen.'],['penilaian',role==='program'?'Penilaian akhir M12':'Review capaian','Tetapkan level capaian sesuai kewenangan.'],['raport','Baca raport','Lihat hasil dan riwayat yang sudah terbit.']];
 return title('Kelompok → pilih mentee','Mulai dari mentee dampingan, lalu buka tugas pemeriksaan atau review.')+`<section class="card"><h2>Mentee dampingan</h2><p class="sub">Belum ada data kelompok atau mentee pada preview. Pada sistem operasional, hanya mentee sesuai penugasan yang muncul.</p><div class="field-grid">${select('previewCohort','Cohort',[])}${select('previewGroup','Kelompok',[])}${select('previewMentee','Mentee',[])}</div><p class="help">Kamu tetap bisa meninjau format tugas di bawah tanpa menambahkan peserta contoh.</p></section><div class="grid">${tasks.map(([f,t,d,view])=>`<section class="card"><h2>${t}</h2><p class="sub">${d}</p><div class="actions"><a class="secondary" href="${previewHref(f,view?{view}:{})}">Lihat format →</a></div></section>`).join('')}</div>`;
}
function previewABCReview(){
 const commitment=query.get('view')==='komitmen';
 return title(commitment?'Tindak lanjut komitmen oleh Asmen':'Pemeriksaan Worksheet ABC oleh Asmen',commitment?'Bandingkan komitmen dengan tindakan dan hasil yang benar-benar terjadi.':'Periksa kejelasan dan kelengkapan jawaban. ABC tidak diberi skor.')+previewSources('Jawaban asli mentee — hanya baca')+`<section class="card"><h2>${commitment?'Hasil pemeriksaan komitmen':'Catatan pemeriksaan ABC'}</h2>${commitment?select('commitmentStatus','Status komitmen',['Belum dijalankan','Sedang dijalankan','Selesai','Perlu dukungan'])+field('commitmentAction','Tindakan yang benar-benar dijalankan','','textarea')+field('commitmentResult','Hasil aktual dan bukti','','textarea')+field('commitmentProof','Tautan bukti aktual','','url')+field('commitmentLearning','Pembelajaran atau hambatan','','textarea')+field('commitmentNext','Tindak lanjut dan dukungan','','textarea'):field('abcReviewNote','Catatan kejelasan dan kelengkapan','','textarea')+field('abcRepair','Minta mentee memperbaiki pengajuan',false,'checkbox')}<div class="notice">Asmen tidak mengubah jawaban mentee dan tidak menetapkan level capaian KPI.</div><div class="actions"><button class="button" disabled>Simpan pemeriksaan</button></div><p class="help">Identitas pemeriksa, versi sumber dan waktu dicatat oleh server pada sistem operasional.</p></section>`;
}
function previewAsmenProgress(){
 return title('Pemeriksaan proses & bukti oleh Asmen','Pisahkan status proses dari level capaian KPI.')+previewSources('Laporan tindakan dan bukti dari mentee')+`<section class="card"><h2>Proses check-in</h2>${select('asmenProcess','Warna proses',['Green','Yellow','Red'])}${field('asmenReason','Alasan warna proses','','textarea')}${field('asmenActionChecked','Tindakan telah saya periksa',false,'checkbox')}${field('asmenEvidenceChecked','Bukti tindakan telah saya periksa',false,'checkbox')}${field('asmenNoImprovement','Yellow sebelumnya belum menunjukkan perbaikan',false,'checkbox')}<p class="help">Green memerlukan konfirmasi tindakan dan bukti. Yellow berulang menjadi Red hanya setelah Asmen mengonfirmasi tidak ada perbaikan.</p></section><section class="card"><h2>Kekuatan dan verifikasi bukti aktual per KPI</h2><p class="sub">Daftar KPI mengikuti POC; hasil aktual tetap berasal dari mentee.</p>${select('asmenEvidenceTier','Bukti terkuat',[[0,'0 · Aktivitas / belum ada bukti hasil'],[1,'1 · Output'],[2,'2 · Mutu'],[3,'3 · Outcome'],[4,'4 · Keberlanjutan']])}${field('asmenVerified','Bukti telah saya periksa dan dapat diverifikasi',false,'checkbox')}${field('asmenEvidenceNote','Alasan dan catatan pemeriksaan bukti','','textarea')}<div class="notice">Penetapan Not Achieved / Progress / Achieve / Exceed dilakukan Mentor atau Tim Penilaian sesuai periode, sesudah pemeriksaan ini.</div><button class="button" disabled>Simpan pemeriksaan bukti</button></section>`;
}
function previewPOCDecision(){
 return title(role==='mentor'?'Kesepakatan POC oleh Mentor':'Baca POC mentee','Baca outcome, baseline, KPI dan patokan M3/M6/M9/M12 sebelum memberi keputusan.')+previewSources('POC yang diajukan mentee — hanya baca')+(role==='mentor'?`<section class="card"><h2>Keputusan kesepakatan</h2>${field('pocDecisionNote','Catatan kesepakatan atau alasan perbaikan','','textarea')}${field('pocDecisionRepair','Minta mentee memperbaiki POC sebelum disepakati',false,'checkbox')}<button class="button" disabled>Simpan keputusan POC</button><p class="help">Jawaban dan target tidak diubah langsung oleh pemeriksa. Mentee mengajukan versi perbaikan; riwayat tetap tersedia.</p></section>`:'');
}
function previewMenteeHome(){return title('Program saya','Isi arah, refleksi, tindakan dan bukti; baca hasil yang sudah diterbitkan.')+`<div class="grid">${[['poc','1 · Susun POC','Tulis outcome, baseline dan target bersama Mentor.'],['abc','2 · Isi Worksheet ABC','Boleh mulai sebelum POC. Tidak diberi skor.'],['progres','3 · Catat tindakan & bukti','Laporkan hasil aktual dan perbaiki pengajuan bila diminta.'],['raport','4 · Baca raport','Hasil review muncul setelah diterbitkan.']].map(([f,t,d])=>`<section class="card"><h2>${t}</h2><p class="sub">${d}</p><div class="actions"><a class="secondary" href="${previewHref(f)}">Buka →</a></div></section>`).join('')}</div>`;}
function renderPreview(){
 let body;
 if(page==='kelompok')body=previewGroup();
 else if(page==='poc'){if(role==='mentee'){editor||={kind:'poc',data:{},month:1};body=pocForm(editor);}else body=previewPOCDecision();}
 else if(page==='abc'){if(role==='mentee'){editor||={kind:'abc',data:{},month:1};body=abcForm(editor);}else body=role==='asmen'?previewABCReview():title('Baca Worksheet ABC','Refleksi dan komitmen mentee sebagai bahan pendampingan.')+previewSources('Jawaban ABC mentee — hanya baca');}
 else if(page==='progres')body=role==='asmen'?previewAsmenProgress():role==='mentee'?(editor?progressForm(editor):title('Tindakan & bukti saya','Isi laporan check-in, catatan mentoring, aktual KPI dan portofolio.')+`<div class="actions"><button class="secondary" data-new="checkin">Lihat formulir check-in</button><button class="secondary" data-new="mentoring">Lihat catatan mentoring</button></div>`+progress()):title('Baca aktual & bukti','Baca hasil mentee dan pemeriksaan Asmen sebelum menetapkan capaian.')+previewSources('Aktual dan hasil pemeriksaan Asmen — hanya baca');
 else if(page==='review')body=['mentor','program'].includes(role)?previewReview():role==='mentee'?previewMenteeHome():previewGroup();
 else if(page==='raport')body=report();
 else body=title('Masukan 360','Bahan pertimbangan enam kompetensi P3, bukan skor tambahan.')+empty('Menunggu kebijakan pengamat','Jenis/jumlah pengamat dan anonimitas belum diputuskan. Pengumpulan belum diaktifkan.');
 const links=role==='mentee'?[['poc','POC'],['abc','Worksheet ABC'],['progres','Tindakan & bukti'],['raport','Raport saya']]:role==='asmen'?[['kelompok-penilaian','Pilih mentee'],['poc','Baca POC'],['abc','Periksa ABC'],['abc','Tindak lanjut komitmen','komitmen'],['progres','Proses & bukti'],['raport','Raport mentee']]:[['kelompok-penilaian','Pilih mentee'],['poc','Sepakati POC'],['abc','Baca ABC'],['progres','Baca bukti'],['penilaian',role==='program'?'Penilaian akhir M12':'Review capaian'],['raport','Raport mentee']];
 $('#content').innerHTML=`<section class="notice"><strong>Preview alur per peran</strong><p>Formulir kosong untuk review. Tidak ada akun nyata, nilai contoh, penyimpanan atau publikasi.</p><label>Lihat sebagai<select id="preview-role">${previewRoles.map(r=>`<option value="${r}" ${r===role?'selected':''}>${previewRoleLabels[r]}</option>`).join('')}</select></label><p class="help">Pilihan peran ini hanya untuk preview; akses operasional tetap diperiksa server.</p></section><nav class="subject-tabs" aria-label="Alur tugas per peran">${links.map(([file,label,view])=>`<a href="${previewHref(file,view?{view}:{})}">${label}</a>`).join('')}</nav><div id="message" role="status"></div>${body}`;
 bind();
 $('#preview-role').onchange=e=>{const r=e.target.value;location.href=(['asmen','mentor'].includes(r)?'kelompok-penilaian':'penilaian')+'.html?peran='+r+'&period='+(r==='program'?12:6);};
 document.querySelectorAll('#assessment [data-record-action],#assessment [data-save-check],#assessment [data-review-save],#assessment [data-publish]').forEach(b=>{b.disabled=true;b.title='Penyimpanan tidak aktif pada preview';});
}
export function mountPreview(){
 reviewPreview=true;role=previewRoles.includes(query.get('peran'))?query.get('peran'):'mentee';
 w={actor:{id:'preview',display_name:'Akun belum dipilih',active:true,roles:[role]},selectedCohort:null,selectedMentee:'preview',cohorts:[],profiles:[],enrolments:[],groups:[],members:[],sessions:[],records:[],staff:[]};
 observerState={available:false,feedback:[],reason:'Pengumpulan 360 belum diaktifkan.'};renderPreview();
}
